const stored   = $getWorkflowStaticData('global');
const lastSeen = stored.lastSeenUrl || '';

const body = items[0].json.data || items[0].json || '';
const html = typeof body === 'string' ? body : JSON.stringify(body);

const dates  = [...html.matchAll(/(\d{2}\/\d{2}\/\d{4}\s*-\s*\d{2}:\d{2})/g)].map(m => m[1].trim());
const links  = [...html.matchAll(/href="(\/fr\/news\/[^"]+)"/g)].map(m => 'https://www.steg.com.tn' + m[1]);
const titles = [...html.matchAll(/<h[2-4][^>]*>([\s\S]*?)<\/h[2-4]>/g)]
  .map(m => m[1].replace(/<[^>]+>/g, '').trim())
  .filter(t => t.length > 5);

const articles = [];
const count = Math.min(links.length, 20);
for (let i = 0; i < count; i++) {
  articles.push({
    date:  dates[i]  || '',
    title: titles[i] || links[i].split('/').pop().replace(/-/g, ' '),
    url:   links[i]
  });
}

const outageKW = ['\u0627\u0646\u0642\u0637\u0627\u0639', 'coupure', 'Coupure', 'interruption', 'panne', 'inqita'];
const outages = articles.filter(a => outageKW.some(kw => a.title.includes(kw) || a.url.includes(kw)));
const result  = outages.length > 0 ? outages : articles.slice(0, 8);

const SFAX_ONLY = true;
const sfaxKW = ['\u0635\u0641\u0627\u0642\u0633', 'Sfax', 'sfax'];
const sfaxArticles = result.filter(a => sfaxKW.some(kw => a.title.includes(kw) || a.url.includes(kw)));
const finalResult  = SFAX_ONLY ? sfaxArticles : result;

if (finalResult.length === 0) {
  return [{ json: { isNew: false, articles: [], latestUrl: '', sfaxCount: 0, allArticles: result } }];
}

const latestUrl = finalResult[0].url;
const isNew     = latestUrl !== lastSeen;

if (isNew) {
  stored.lastSeenUrl = latestUrl;
}

return [{ json: { isNew, articles: finalResult, allArticles: result, latestUrl, lastSeen, sfaxCount: sfaxArticles.length } }];

const articles = $json.articles || [];
const rows = articles.map(a => `<tr><td style='padding:9px 14px;font-size:0.82rem;color:#666;white-space:nowrap'>${a.date}</td><td style='padding:9px 14px'><a href='${a.url}' style='color:#1a1a2e;font-weight:600;text-decoration:none'>${a.title}</a></td><td style='padding:9px 14px'><a href='${a.url}' style='color:#1565c0;font-size:0.8rem;white-space:nowrap'>Lire →</a></td></tr>`).join('');
const now = new Date().toLocaleString('fr-TN', {timeZone:'Africa/Tunis'});
const html = `<!DOCTYPE html><html><head><meta charset='UTF-8'/></head><body style='font-family:Arial,sans-serif;background:#f4f6f9;padding:20px'><div style='max-width:700px;margin:auto'><div style='background:#b71c1c;color:#fff;padding:16px 20px;border-radius:8px 8px 0 0'><h2 style='margin:0;font-size:1.15rem'>⚡ STEG — Nouveaux avis d'interruption électrique</h2><p style='margin:4px 0 0;font-size:0.8rem;opacity:0.85'>${now} · hack-olive · steg.com.tn</p></div><table style='width:100%;border-collapse:collapse;background:#fff;border-radius:0 0 8px 8px;overflow:hidden;box-shadow:0 1px 4px rgba(0,0,0,.1)'><thead><tr style='background:#1a1a2e;color:#fff'><th style='padding:9px 14px;text-align:left;font-size:0.8rem'>Date</th><th style='padding:9px 14px;text-align:left;font-size:0.8rem'>Avis</th><th style='padding:9px 14px;text-align:left;font-size:0.8rem'></th></tr></thead><tbody>${rows}</tbody></table><p style='margin-top:14px;font-size:0.75rem;color:#aaa;text-align:center'>Source: <a href='https://www.steg.com.tn/fr/news' style='color:#aaa'>steg.com.tn/fr/news</a> · Vérification automatique toutes les 3 heures</p></div></body></html>`;
const today = new Date().toLocaleDateString('fr-TN', {timeZone:'Africa/Tunis'});
return [{json:{subject:`⚡ STEG — ${articles.length} avis de coupure (dont ${$json.sfaxCount} Sfax) — ${today}`,html}}];

const r = items[0].json;
const status = r.success ? '✅ Réentraînement réussi' : '❌ Réentraînement échoué';
console.log(`${status} — durée: ${r.duration_s}s — ${r.trained_at}`);
return [{json:{retrain_status: status, duration_s: r.duration_s, trained_at: r.trained_at, success: r.success}}];
